// AI governance modules AI23 (agentic AI), AI24 (sectors) and AI25 (incident response) — full theory.
import { X } from './aic-x-fig.js';
const P = x => ({ k: 'p', x }), H = x => ({ k: 'h', x }), S = x => ({ k: 'simple', x }), BR = x => ({ k: 'br', x });
const U = x => ({ k: 'ul', x }), O = x => ({ k: 'ol', x }), AP = (s, x, t) => ({ k: 'ap', s, x, t });
const FIG = (svg, cap) => ({ k: 'fig', svg, cap }), CMP = (t, h, r) => ({ k: 'cmp', t, h, r }), FLOW = (t, s, loop, v) => ({ k: 'flow', t, s, loop, v }), CARDS = c => ({ k: 'cards', c });

export const X_AI2 = [
{
 id: 'ai23', lv: 4, name: 'Governing Agentic AI',
 goal: 'Understand what makes AI agents different, the new risks they create, and how to govern them: autonomy levels, permissions, approvals, identity, monitoring, accountability and vendor agents.',
 map: ['Emerging risk', 'OWASP LLM06', 'ISO/IEC 42001 A.6, A.9', 'NIST AI 600-1'],
 res: [['OWASP Top 10 for LLM Applications (LLM06 Excessive Agency)', 'https://genai.owasp.org/llm-top-10/'], ['Anthropic: Building effective agents', 'https://www.anthropic.com/research/building-effective-agents'], ['Model Context Protocol', 'https://modelcontextprotocol.io/'], ['MITRE ATLAS', 'https://atlas.mitre.org/']],
 ls: [
  { t: 'What makes agents different', blocks: [
    S('An **AI agent** pursues a goal by **planning steps and taking actions** in other systems, with limited human input. The shift from “AI that advises” to “AI that acts” changes the risk profile fundamentally.'),
    H('From assistant to agent'),
    P('Most early generative AI deployments were assistants: a person asks, the model answers, the person decides what to do. Agents combine a language model with **tools** (APIs, databases, email, browsers, payment systems), **memory** and a **control loop** that lets the model decide its next step, observe results and continue. Examples include agents that triage IT tickets and reset passwords, reconcile invoices, update CRM records, book travel, or write and run code.'),
    H('Why the risk changes'),
    CARDS([['Actions, not words', 'Errors become transactions, changes or messages.', 'Wrong payment sent'], ['Compounding steps', 'A small early mistake grows over many steps.', 'Wrong customer updated repeatedly'], ['New attack paths', 'Content the agent reads can redirect it.', 'Instruction hidden in an email'], ['Identity confusion', 'Whose authority does the agent act under?', 'Agent uses an admin account'], ['Speed and scale', 'Thousands of actions before anyone notices.', 'Mass email to customers'], ['Accountability gaps', 'Who is responsible for an agent’s decision?', '“The agent did it”']]),
    H('Agents in regulation'),
    P('Most AI laws do not yet have agent-specific rules, but existing obligations apply fully: the organisation is responsible for actions taken on its behalf; data protection rules apply to what agents access; high-risk use cases remain high-risk; human-oversight duties still apply. Security frameworks address agents directly — **excessive agency** is a named risk in the OWASP Top 10 for LLM Applications.'),
    BR('Treat an agent as a **digital worker** or **privileged service account** with judgement: it needs a defined role, least-privilege access, supervision, logging and an owner — like any person or system with authority to act.'),
    AP(['Identify which AI systems take actions, not just produce text.', 'List the actions each can take and their potential impact.', 'Assign an owner accountable for each agent.'])],
   ex: 'An IT-support agent reset 300 passwords in an hour after misreading a phishing-awareness email as a request — fast, confident and wrong. The fix: password resets now require user confirmation.' },
  { t: 'Levels of autonomy', blocks: [
    S('Not all agents are equally autonomous. Classifying the **level of autonomy** helps decide how much control and oversight each needs.'),
    H('A practical autonomy scale'),
    CMP('Autonomy levels', ['Level', 'Description', 'Example', 'Typical controls'], [['0 — Assist', 'Suggests; human acts', 'Drafts an email', 'Standard GenAI controls'], ['1 — Prepare', 'Prepares actions; human approves each', 'Prepares a payment for approval', 'Approval workflow, logging'], ['2 — Act within limits', 'Acts alone within strict limits; human reviews samples', 'Resets passwords after user confirmation', 'Hard limits, monitoring, sampling'], ['3 — Act broadly', 'Acts across systems with exceptions escalated', 'Handles a full refund process', 'Strong limits, real-time monitoring, kill switch, high-tier approval'], ['4 — Self-directed', 'Sets sub-goals and acts with little oversight', 'Research agent operating for days', 'Exceptional justification; rarely appropriate for business processes']]),
    H('Matching autonomy to risk'),
    P('The appropriate level depends on the **impact and reversibility** of actions. Reading and summarising may be safe at higher autonomy; moving money, changing customer records, sending external communications or deleting data usually warrants level 1 or tightly bounded level 2. Autonomy should be increased step by step, with evidence from monitoring at each step.'),
    H('Documenting autonomy decisions'),
    P('For each agent, record the autonomy level, the actions permitted at that level, limits (amounts, volumes, scopes), approval rules and the evidence that justified it. Treat changes in autonomy as **material changes** requiring reassessment.'),
    BR('This resembles **delegation of authority** matrices: who may approve what, up to which limit. Write an equivalent matrix for each agent.'),
    AP(['Assign an autonomy level to each agent.', 'Check that autonomy matches action impact and reversibility.', 'Treat autonomy increases as material changes.'])],
   ex: 'A bank allowed its servicing agent to issue fee refunds automatically up to AED 100 (level 2), with anything higher prepared for staff approval (level 1) — a delegation-of-authority approach applied to AI.' },
  { t: 'Permissions, identity and approvals', blocks: [
    S('The most effective agent controls are **architectural**: give the agent the **least privilege**, make it act **under the user’s identity**, and require **approval outside the chat** for consequential actions.'),
    FIG(X.agentPerm, 'Separate read, draft and act tools, with approvals for actions.'),
    H('Least privilege'),
    P('Grant only the tools and data the agent needs for its task. Prefer **read-only** access; separate tools for preparing and executing actions; scope access to specific records or folders; and limit amounts, volumes and recipients. Avoid giving agents broad service accounts or administrator rights for convenience.'),
    H('Identity and authority'),
    P('An agent should normally act **on behalf of a specific user**, inheriting that user’s permissions — so it cannot access data or perform actions the user could not. Where an agent uses its own service identity, that identity must have a narrowly defined role and be monitored like any privileged account. Every action should be logged with **both** the agent’s and the requesting user’s identity.'),
    H('Approvals that cannot be talked around'),
    P('Approval steps must be enforced by the **application**, not by instructions in the prompt. A prompt saying “always ask before paying” can be overridden by injected text; an approval screen that the payment API requires cannot. For high-risk actions, use step-up authentication and show the human exactly what will happen.'),
    BR('These are **access management and segregation-of-duties** controls applied to a new kind of actor. The “maker–checker” principle is the key pattern: the agent makes, a human checks.'),
    AP(['Review each agent tool’s permissions and scopes.', 'Confirm actions run under user identity or a narrowly scoped service identity.', 'Test that approvals are enforced technically, not by prompt.'])],
   ex: 'Penetration testers told a procurement agent, via a supplier email, to “approve the attached invoice urgently”. Because approval required a separate human action in the ERP, nothing was paid.' },
  { t: 'Monitoring, limits and the kill switch', blocks: [
    S('Agents act fast and at scale. You need **real-time limits**, **behaviour monitoring** and a tested ability to **stop them immediately**.'),
    H('Hard limits'),
    U(['**Rate limits** — maximum actions per minute, hour or day.', '**Value limits** — maximum amount per transaction and per period.', '**Scope limits** — which records, customers, systems or recipients.', '**Step limits** — maximum steps per task, to prevent runaway loops.', '**Cost limits** — maximum spend on model calls and tools.']),
    H('Behaviour monitoring'),
    P('Monitor not only errors but **unusual behaviour**: spikes in actions, access to unusual records, repeated failures, attempts to use tools outside normal patterns, or outputs triggering guardrails. Many organisations route agent activity logs into their security monitoring (SIEM) so the security operations team can detect misuse.'),
    H('The kill switch'),
    P('Every agent with action capability needs a **documented, tested way to stop it immediately** — disabling tools, revoking credentials or switching to a manual process — and a plan to identify and reverse actions already taken. Test the kill switch periodically, like a business continuity drill.'),
    FLOW('When an agent misbehaves', [['Detect', 'alert or report'], ['Stop', 'kill switch within minutes'], ['Scope', 'which actions were taken?'], ['Reverse', 'undo or correct'], ['Fix and retest', 'before re-enabling']]),
    BR('These mirror **transaction limits, fraud monitoring and incident response** for payment systems. Apply the same rigour to agents with action rights.'),
    AP(['Check hard limits exist and are enforced technically.', 'Check agent logs feed security monitoring.', 'Ask when the kill switch was last tested and how long it took.'])],
   ex: 'A marketing agent’s step limit stopped it after 50 iterations when it got stuck re-sending a draft — without the limit it would have emailed the same customers repeatedly.' },
  { t: 'Accountability, vendors and multi-agent systems', blocks: [
    S('Someone must be **accountable** for each agent’s actions. With vendor agents and agents that call other agents, accountability must be **designed in**, not assumed.'),
    H('Accountability for agents'),
    P('Each agent needs a named **business owner** responsible for its outcomes, a **technical owner** for its operation, and clear rules about which decisions it may take. Customers, regulators and courts will hold the organisation responsible for agent actions, as they did for chatbot statements in the Air Canada case.'),
    H('Vendor agents'),
    P('Many SaaS platforms now include agents that act inside the platform (for example, CRM agents that update records and email customers). Assessing these requires asking the vendor: what actions can the agent take, under whose permissions, with which configurable approvals and limits, what is logged, and how can it be turned off? Default settings are often more permissive than an organisation would choose.'),
    H('Multi-agent systems'),
    P('Some designs use several agents that delegate tasks to one another or connect to external agents. This adds complexity: errors and injected instructions can pass between agents, and it becomes harder to trace who decided what. Controls include limiting which agents can call which, treating messages between agents as untrusted input, and end-to-end logging with correlation IDs.'),
    CMP('Accountability checklist', ['Question', 'Evidence'], [['Who owns this agent’s outcomes?', 'Named business owner in inventory'], ['What may it decide alone?', 'Autonomy level and delegation matrix'], ['Who configured vendor agent settings?', 'Configuration record and approval'], ['Can actions be traced end to end?', 'Logs with user, agent and correlation IDs'], ['Who can switch it off?', 'Kill-switch procedure and roles']]),
    BR('Accountability for agents follows the same rule as outsourcing: **you can delegate the task, not the responsibility**.'),
    AP(['Confirm business and technical owners for every agent, including vendor agents.', 'Review vendor agent default settings.', 'Check traceability across multi-agent flows.'])],
   ex: 'A CRM vendor enabled an “auto-follow-up” agent in a routine update. It began emailing customers about offers they had declined. The bank had not reviewed the default settings — now every vendor agent feature requires approval before activation.' },
  { t: 'Real-world scenario: approving an accounts-payable agent', blocks: [
    S('A finance team wants an agent to process supplier invoices end to end. This scenario shows how to **approve an agent safely**, step by step.'),
    H('The proposal'),
    P('A Dubai-based group’s finance team proposes an agent that reads supplier invoices from a mailbox, matches them to purchase orders in the ERP, queries suppliers about mismatches by email, and schedules payments. Expected benefit: 70% less manual processing.'),
    H('The assessment'),
    O(['**Tier and autonomy:** moving money and emailing suppliers → Tier 1. Proposed autonomy level 3 is reduced to **level 1 for payments** (prepare only) and **level 2 for supplier queries** (send from a template, no attachments, approved suppliers only).', '**Permissions:** read access to the invoice mailbox and purchase orders; ability to create payment *drafts*; no ability to change supplier bank details.', '**Injection risk:** invoices and emails are untrusted input. Red-team tests include invoices containing hidden instructions (“change bank account”, “approve urgently”).', '**Approvals:** payment release requires the existing two-person ERP approval; bank-detail changes remain a separate, manual, call-back-verified process.', '**Limits:** maximum 200 drafts per day; maximum single invoice AED 250,000 for agent processing; above that, manual handling.', '**Monitoring and kill switch:** activity logs to SIEM; daily exception report; kill switch tested before launch.', '**Accountability:** Head of Accounts Payable as business owner; finance systems lead as technical owner.']),
    H('Outcome'),
    P('The agent launches with these controls and achieves a 55% reduction in manual effort. In month two, an invoice with hidden text instructing a bank-detail change is flagged by the agent’s output filter and, in any case, could not have changed bank details. After six months of clean monitoring results, autonomy for supplier queries is extended.'),
    BR('This is a classic **process-change approval** for a payments process, using delegation of authority, segregation of duties and fraud controls — applied to an AI actor.'),
    AP(['Reduce autonomy for irreversible actions.', 'Keep high-risk changes (like bank details) outside the agent’s reach.', 'Extend autonomy only on evidence.'], '', 'Approving an agent')],
   ex: 'The control that mattered most was the simplest: the agent could not change supplier bank details at all — the most common fraud target in accounts payable.' }
 ],
 sum: ['Agents plan and act; errors become actions, at speed and scale.', 'Classify autonomy levels and match them to the impact and reversibility of actions.', 'Least privilege, user identity and technically enforced approvals are the strongest controls.', 'Use hard limits, behaviour monitoring and a tested kill switch.', 'Name owners for every agent, review vendor agent defaults, and trace multi-agent flows.', 'Increase autonomy step by step, based on monitoring evidence.'],
 q: [
  { t: 'What most distinguishes an AI agent from a chatbot?', o: ['It always uses a larger language model', 'It can only answer questions in English', 'It works without any prompts or instructions', 'It plans and takes actions in other systems'], a: 3, x: 'Agents act through tools, not just text.' },
  { t: 'Why must approvals be enforced by the application rather than the prompt?', o: ['Prompt instructions can be overridden by injected text', 'Prompts are too expensive to run for every transaction', 'Laws forbid using prompts for financial approvals', 'Applications always respond faster than prompts do'], a: 0, x: 'Technical enforcement cannot be talked around.' },
  { t: 'An agent should normally act under:', o: ['A shared administrator account for all agents', 'The requesting user’s identity and permissions', 'The vendor’s own support account and rights', 'No identity, so that actions stay anonymous'], a: 1, x: 'Inheriting user permissions prevents access beyond the user’s rights.' },
  { t: 'Which limit prevents runaway loops?', o: ['Value limit', 'Rate limit on logins', 'Step limit per task', 'Data retention limit'], a: 2, x: 'Step limits cap the number of iterations.' },
  { t: 'A vendor enables an agent feature in an update. What control was missing?', o: ['A larger budget for the customer service team', 'A new logo for the bank’s email templates', 'More training data for the vendor’s model', 'Approval before activating vendor agent features'], a: 3, x: 'Vendor agent defaults should be reviewed and approved.' },
  { t: 'Appropriate autonomy for an agent releasing payments is usually:', o: ['Prepare only, with human approval', 'Self-directed with no human review', 'Act broadly and review monthly', 'Act freely with no logging at all'], a: 0, x: 'Irreversible financial actions need maker–checker control.' }
 ]
},
{
 id: 'ai24', lv: 4, name: 'AI in Key Sectors: Banking, Insurance, Health, HR and Government',
 goal: 'Understand how AI risks, rules and expectations differ across banking, insurance, healthcare, employment and the public sector, with UAE, India and EU anchors.',
 map: ['Sector deep dive', 'EU AI Act Annex I and III', 'CBUAE', 'RBI FREE-AI'],
 res: [['CBUAE Rulebook', 'https://rulebook.centralbank.ae/'], ['RBI FREE-AI framework', 'https://www.rbi.org.in/scripts/BS_PressReleaseDisplay.aspx?prid=61018'], ['WHO: Ethics and governance of AI for health', 'https://www.who.int/publications/i/item/9789240029200'], ['EU AI Act Annex III', 'https://artificialintelligenceact.eu/annex/3/']],
 ls: [
  { t: 'Why sector context matters', blocks: [
    S('The same AI technique carries **very different risks** in different sectors. A recommendation model is low-risk for films and high-risk for medical treatment. Sector rules, regulators and harms shape what “good governance” means.'),
    H('Three drivers of sector differences'),
    CARDS([['Harm', 'What can go wrong for people.', 'Lost savings, denied treatment, lost job'], ['Regulation', 'Who supervises and what they expect.', 'Central banks, health authorities, labour law'], ['Existing controls', 'What risk frameworks already exist.', 'Model risk, clinical safety, HR policy']]),
    H('Using existing sector frameworks'),
    P('Most regulated sectors already have mature risk frameworks: banks have model risk management, insurers have pricing and claims governance, hospitals have clinical safety and medical device rules, employers have HR and anti-discrimination policies, governments have administrative law and procurement rules. Effective AI governance **extends** these frameworks rather than creating a separate parallel system.'),
    CMP('Sector overview', ['Sector', 'Typical high-risk AI', 'Key anchors'], [['Banking', 'Credit scoring, fraud/AML, customer chatbots', 'CBUAE guidance, RBI FREE-AI, model risk standards'], ['Insurance', 'Pricing, underwriting, claims triage', 'Insurance regulators, EU Annex III (life/health)'], ['Health', 'Diagnosis support, triage, imaging', 'Medical device rules, health data laws, EU Annex I'], ['Employment', 'Hiring, monitoring, promotion', 'Labour law, EU Annex III, Art. 5'], ['Government', 'Benefits, inspections, citizen services', 'Administrative law, UAE/India public-sector AI policies, EU Annex III, FRIA']]),
    BR('When assessing AI in a sector, start by asking: **which existing sector risk framework should this AI already sit inside?**'),
    AP(['Identify the sector regulator and existing risk frameworks.', 'Check AI is integrated into them.', 'Use sector-specific harms to calibrate impact ratings.'])],
   ex: 'A bank’s AI governance became much stronger once AI models were brought under the existing model risk management framework instead of a separate “innovation” process.' },
  { t: 'Banking and financial services', blocks: [
    S('Banks use AI for **credit, fraud, AML, customer service, trading and operations**. Supervisors expect AI to be governed through **model risk management, consumer protection and outsourcing** frameworks.'),
    H('Main AI uses and risks'),
    U(['**Credit decisions** — fairness, explanation, affordability, drift.', '**Fraud and AML** — false positives harming customers, missed crime, regulatory reporting.', '**Customer chatbots** — mis-selling, wrong information, data leakage.', '**Marketing and pricing** — unfair targeting or pricing of vulnerable customers.', '**Operations and coding assistants** — security and confidentiality.']),
    H('Supervisory expectations'),
    P('In the UAE, the **CBUAE’s February 2026 guidance note** expects board accountability, AI risk within enterprise risk management, an AI model inventory aligned with the **2022 Model Management Standards**, bias testing on representative data, security- and privacy-by-design, and for outsourced AI, audit rights and immediate cessation capability. In the DIFC and ADGM, the DFSA and FSRA apply their own expectations. In India, **RBI’s FREE-AI framework** (August 2025) recommends board-approved AI policies, AI inventories, risk-based governance, model audits, consumer protection and incident reporting, alongside digital lending rules. In the EU, credit scoring is **Annex III high-risk**.'),
    H('Model risk management as the backbone'),
    P('Banks typically manage models through a lifecycle: inventory, tiering, development standards, independent validation, approval, monitoring and periodic revalidation. Extending this to AI means adding fairness, explainability, GenAI-specific testing and broader model definitions (including vendor and GenAI models).'),
    BR('If you have audited model risk management, you already know most of the structure. Check that **AI and GenAI** are within its definitions and that **fairness and customer impact** are in validation scope.'),
    AP(['Check AI is within the model risk framework.', 'Map CBUAE or RBI expectations to controls.', 'Check consumer-impact metrics are monitored.'])],
   ex: 'A UAE bank discovered its GenAI chatbot and several vendor models were outside the model inventory because the definition only covered “statistical models”. Updating the definition added 14 systems.' },
  { t: 'Insurance', blocks: [
    S('Insurers use AI for **underwriting, pricing, claims and fraud**. The key risks are **unfair pricing, unjustified claim denials and exclusion of vulnerable customers**.'),
    H('Main AI uses and risks'),
    U(['**Underwriting and pricing** — models using many data sources can produce prices that indirectly discriminate or penalise vulnerable groups; “price optimisation” based on willingness to pay raises fairness concerns.', '**Claims triage and automation** — faster payments, but risk of wrongful denials or unfair fraud referrals.', '**Fraud detection** — false positives delay legitimate claims.', '**Customer service** — chatbots giving wrong coverage information (as in the India insurer scenario earlier in this academy).']),
    H('Regulatory anchors'),
    P('Under the EU AI Act, AI used for **risk assessment and pricing in life and health insurance** is **Annex III high-risk**, and deployers must perform a **FRIA**. Insurance regulators in many jurisdictions expect fair treatment of customers, explainable pricing and robust claims handling. Health insurance also involves sensitive health data, triggering stricter data protection rules.'),
    H('Assessment focus'),
    CMP('What to check in insurance AI', ['Area', 'Key question'], [['Pricing data', 'Are any features proxies for protected characteristics or vulnerability?'], ['Pricing outcomes', 'How do prices differ across groups, and are differences justified by risk?'], ['Claims automation', 'What is the error rate for auto-decisions, and how are denials reviewed?'], ['Fraud referrals', 'Are referral rates fair across providers and customers?'], ['Transparency', 'Can customers understand price and claim decisions?']]),
    BR('Insurance has long-standing **actuarial governance**. AI assessment adds fairness testing on outcomes and explanation of complex models to existing actuarial review.'),
    AP(['Check pricing features for proxies.', 'Analyse price and claim outcomes by group.', 'Check review of automated denials.'])],
   ex: 'An insurer found its claims-automation model denied physiotherapy claims from one region more often — the region’s clinics used older coding. Manual review was added until the model was retrained.' },
  { t: 'Healthcare', blocks: [
    S('Healthcare AI can **save lives or cause harm**. Many clinical AI tools are regulated as **medical devices**, and health data is among the most sensitive data there is.'),
    H('Main AI uses and risks'),
    U(['**Diagnosis support and imaging** — missed or false diagnoses; performance differences across populations and equipment.', '**Triage and prioritisation** — wrong urgency assessments.', '**Clinical documentation** — ambient scribes and summarisation may introduce errors into records.', '**Patient chatbots** — unsafe medical advice.', '**Operational AI** — scheduling, capacity forecasting (lower risk).']),
    H('Regulatory anchors'),
    P('Software that diagnoses, prevents, monitors or treats disease is often a **medical device** under medical device regulations (in the EU, the MDR or IVDR). Such AI is **high-risk under the EU AI Act via Annex I**. In the UAE, health data is governed by sector-specific health data law and health-authority policies (such as those of the Department of Health — Abu Dhabi and the Dubai Health Authority), rather than the federal PDPL. In India, the DPDP Act applies to digital health data, alongside medical device rules where claims qualify. The **WHO** has published guidance on the ethics and governance of AI for health.'),
    H('Assessment focus'),
    CMP('What to check in health AI', ['Area', 'Key question'], [['Regulatory status', 'Is it a medical device? Is it approved or certified?'], ['Clinical validation', 'Was it validated on populations and equipment like ours?'], ['Human oversight', 'Do clinicians review outputs independently, without automation bias?'], ['Data', 'Lawful basis for health data; hosting and access controls'], ['Safety monitoring', 'How are errors and near misses reported and learned from?']]),
    BR('Healthcare already has **clinical governance and patient safety** systems. AI incidents should flow into the same incident and learning processes.'),
    AP(['Confirm medical-device status and approvals.', 'Check local clinical validation.', 'Check clinician oversight and safety reporting.'])],
   ex: 'A hospital’s imaging AI, validated abroad on different scanners, missed more findings on its own equipment. Local validation before go-live caught the gap.' },
  { t: 'Employment and the public sector', blocks: [
    S('AI that decides about **jobs** or delivers **public services** affects people’s livelihoods and rights, and often there is **no alternative provider** for the person affected. Both sectors carry special obligations.'),
    H('Employment'),
    P('HR AI includes CV screening, video interviews, skills assessments, scheduling, productivity monitoring, promotion and termination support. Risks include discrimination, intrusive monitoring, emotion inference and lack of transparency. Under the EU AI Act, employment uses are **Annex III high-risk**; emotion recognition in the workplace is **prohibited**; deployers must inform workers and their representatives. Labour and anti-discrimination laws apply everywhere, and data protection rules limit monitoring.'),
    H('Public sector'),
    P('Governments use AI for benefits eligibility, fraud detection, inspections, citizen chatbots, document processing and planning. Public bodies have particular duties: lawful, fair and transparent administrative decisions, equal treatment and access to remedies. The Dutch childcare benefits scandal showed the harm of opaque, discriminatory risk profiling. Under the EU AI Act, public bodies deploying high-risk AI must perform a **FRIA**, and high-risk systems already used by public authorities must comply by **2 August 2030**. In the UAE, federal and emirate AI policies and the UAE Charter guide public-sector AI; in India, the AI Governance Guidelines and sector rules apply.'),
    CMP('Special considerations', ['Area', 'Employment', 'Public sector'], [['People affected', 'Candidates, employees', 'Citizens, residents, businesses'], ['Key harms', 'Discrimination, surveillance, unfair dismissal', 'Wrongful denial of benefits, unequal treatment, loss of trust'], ['Transparency', 'Notices to candidates and workers', 'Public explanations, publication of AI use'], ['Redress', 'HR appeal, labour courts', 'Administrative appeal, ombudsman, courts'], ['Extra duties', 'Worker consultation (EU)', 'FRIA (EU), procurement and public-law duties']]),
    BR('In both sectors, **power imbalance** is high — people cannot easily walk away. Weight impact ratings accordingly and insist on human decisions and accessible redress.'),
    AP(['Check prohibited workplace uses are excluded.', 'Check notices and consultation for HR AI.', 'For public bodies, check transparency, redress and FRIA where applicable.'])],
   ex: 'A government benefits agency added a rule: no application may be refused based on an AI risk score alone; every refusal needs a caseworker decision with stated reasons.' },
  { t: 'Real-world scenario: one group, many sectors', blocks: [
    S('Conglomerates in the Gulf and India often span **several sectors**. A single AI governance programme must handle **sector-specific rules** within one framework.'),
    H('The situation'),
    P('A UAE-headquartered group owns a bank (onshore), an insurance company (onshore), a hospital network (Abu Dhabi and Dubai), a large retail chain, and an IT services company in Hyderabad. The group board wants one AI governance programme.'),
    H('The design'),
    U(['**Group layer:** one AI policy mapped to the UAE Charter and India’s sutras; group AI committee; common inventory, tiering, assessment template and ISO/IEC 42001-based management system.', '**Sector modules:** banking — CBUAE guidance and model risk management; insurance — pricing fairness and claims governance; health — medical-device status, clinical validation and health data rules; retail — consumer protection and marketing; IT services — client contract obligations, DPDP and security.', '**Shared services:** central red-team and validation capability; shared monitoring tooling; group AI literacy programme with sector-specific modules.', '**Reporting:** each subsidiary board receives its sector view; the group board sees the consolidated picture.']),
    H('Lessons'),
    P('Common foundations (inventory, method, tooling, training) save cost and make risk comparable across the group. Sector modules ensure each business meets its regulator’s expectations. Clear ownership at subsidiary level prevents the group function from becoming a bottleneck.'),
    BR('This is how groups run **integrated GRC**: common framework, sector-specific overlays, local ownership, consolidated reporting.'),
    AP(['Build a common group foundation.', 'Add sector modules mapped to each regulator.', 'Report by subsidiary and consolidated.'], '', 'Designing a multi-sector AI programme')],
   ex: 'Sharing one red-team capability across the bank, insurer and hospital network cut testing costs by 40% and spread lessons quickly — a prompt-injection fix found in the bank’s chatbot was applied to the hospital’s patient assistant the same week.' }
 ],
 sum: ['Sector context changes harm, regulation and existing controls.', 'Banking: integrate AI into model risk, consumer protection and outsourcing; CBUAE and RBI anchors.', 'Insurance: pricing fairness, claims automation and EU Annex III for life and health.', 'Health: medical-device status, local clinical validation, health data rules, clinician oversight.', 'Employment and public sector: high power imbalance; human decisions, transparency and redress.', 'Multi-sector groups need a common foundation plus sector modules.'],
 q: [
  { t: 'Where should a bank’s AI models usually be governed?', o: ['Within the model risk management framework, extended for AI', 'In a separate innovation lab with its own approval process', 'By the vendor alone, since it supplies most of the models', 'Only by the IT security team as part of cyber controls'], a: 0, x: 'Extending existing frameworks avoids gaps and duplication.' },
  { t: 'Under the EU AI Act, AI for life and health insurance pricing is:', o: ['Minimal risk', 'Annex III high-risk', 'Prohibited', 'Only a transparency case'], a: 1, x: 'Annex III point 5 covers life and health insurance risk assessment and pricing.' },
  { t: 'A diagnostic AI tool is often regulated as:', o: ['A marketing tool', 'An HR system', 'A medical device', 'A payment service'], a: 2, x: 'Clinical AI is frequently medical-device software.' },
  { t: 'Why is local clinical validation important?', o: ['Laws forbid hospitals from using any foreign-built models', 'Local validation reduces the licence fees for the tool', 'Local validation replaces the need for clinician review', 'Performance can differ with local populations and equipment'], a: 3, x: 'Validation elsewhere may not reflect local conditions.' },
  { t: 'Which EU obligation applies to public bodies deploying high-risk AI?', o: ['A fundamental rights impact assessment', 'Publishing the model as open source', 'No additional obligations of any kind', 'Moving all data outside the European Union'], a: 0, x: 'Article 27 requires a FRIA for public-body deployers.' },
  { t: 'Best design for a multi-sector group?', o: ['Separate unconnected programmes per company', 'Common foundation plus sector-specific modules', 'One policy with no sector detail', 'Leave governance to each vendor'], a: 1, x: 'This balances consistency with regulator-specific needs.' }
 ]
},
{
 id: 'ai25', lv: 5, name: 'AI Incident Response in Depth',
 goal: 'Plan and run AI incident response: defining AI incidents, detection, triage and severity, containment, notification across EU, UAE and India, root cause, communication and learning.',
 map: ['Operational resilience', 'EU AI Act Art. 73', 'ISO/IEC 42001 A.8.4, 10.2', 'OECD AI Incidents'],
 res: [['OECD AI Incidents Monitor', 'https://oecd.ai/en/incidents'], ['AI Incident Database', 'https://incidentdatabase.ai/'], ['EU AI Act Article 73 (serious incidents)', 'https://artificialintelligenceact.eu/article/73/'], ['MeitY DPDP framework', 'https://www.meity.gov.in/data-protection-framework']],
 ls: [
  { t: 'What counts as an AI incident', blocks: [
    S('An **AI incident** is an event where an AI system causes, or nearly causes, **harm** — to people, the organisation or society. Defining AI incidents clearly is the first step to detecting and handling them.'),
    H('Beyond security incidents'),
    P('Traditional incident management focuses on security breaches and outages. AI incidents include these, but also failures where the system works exactly as designed yet produces harm: discriminatory outcomes, wrong decisions at scale, harmful generated content, unsafe advice, or an agent taking an unintended action. These may never trigger a security alert.'),
    CARDS([['Wrong decisions', 'Systematic errors affecting people.', 'Thousands of claims wrongly denied'], ['Discrimination', 'Unfair outcomes for a group.', 'One nationality over-flagged'], ['Harmful content', 'Toxic, false or dangerous output.', 'Chatbot gives unsafe advice'], ['Data exposure', 'Personal or confidential data leaked.', 'Assistant reveals another customer’s data'], ['Security attack', 'Injection, poisoning, model theft.', 'Agent manipulated via email'], ['Uncontrolled action', 'Agent or automation acts wrongly.', 'Mass emails sent'], ['Near miss', 'Harm narrowly avoided.', 'Wrong payment caught at approval']]),
    H('Severity'),
    P('Define severity levels using impact on people (number affected, seriousness, reversibility), legal and regulatory exposure, financial loss and reputational effect. Severity drives escalation, response speed and notification decisions.'),
    H('Serious incidents under the EU AI Act'),
    P('The EU AI Act defines a **serious incident** for high-risk systems as one that directly or indirectly leads to death or serious harm to health, serious and irreversible disruption of critical infrastructure, infringement of obligations protecting fundamental rights, or serious harm to property or the environment. Providers must report these to market surveillance authorities.'),
    BR('Add AI incident categories to your existing **incident taxonomy** and severity matrix, rather than creating a separate process. The AI-specific additions are categories for fairness, harmful output and model failure.'),
    AP(['Check the incident taxonomy includes AI-specific categories.', 'Check severity criteria include impact on people.', 'Check near misses are recorded.'])],
   ex: 'A bank added three categories to its incident system — “AI wrong decisions”, “AI unfair outcome”, “AI harmful output”. Within a quarter, 11 AI incidents were logged that would previously have been treated as routine complaints.' },
  { t: 'Detection and triage', blocks: [
    S('AI incidents are often detected **not by alarms** but by **complaints, staff observations, monitoring trends or the media**. Good detection connects these sources; good triage decides quickly how serious it is.'),
    FIG(X.incident, 'The AI incident lifecycle.'),
    H('Detection sources'),
    U(['**Monitoring alerts** — drift, performance, fairness, guardrail triggers, unusual agent actions.', '**Complaints and appeals** — tagged when they mention AI or automated decisions.', '**Staff reports** — reviewers noticing odd outputs; a simple “report an AI concern” channel.', '**External reports** — customers, researchers, journalists, regulators, social media.', '**Audits and tests** — red-team findings, validation results, internal audit.']),
    H('Triage questions'),
    O(['What happened, and is it still happening?', 'Which system and version, and since when?', 'Who is affected, how many, and how seriously?', 'Is personal data involved?', 'Could it be a serious incident under the EU AI Act, a personal-data breach, or a sector-reportable event?', 'What immediate containment is possible?']),
    H('Speed matters'),
    P('Notification deadlines can start at awareness: under GDPR, 72 hours from becoming aware of a personal-data breach; India’s CERT-In directions require reporting of specified cyber incidents within 6 hours; the DPDP Rules require a detailed report to the Data Protection Board within 72 hours. Slow triage can turn a manageable incident into a compliance failure.'),
    BR('Use your existing **incident triage** process and on-call arrangements; add an AI specialist to the triage team for AI-related events, and train frontline staff to recognise AI incidents.'),
    AP(['Check complaints are tagged for AI involvement.', 'Check a simple staff and public reporting channel exists.', 'Check triage includes notification screening.'])],
   ex: 'A social media post showing a chatbot giving offensive answers was spotted by the communications team at 9 a.m.; by 9:40 the AI incident team had disabled the feature and started triage.' },
  { t: 'Containment and recovery', blocks: [
    S('Containment stops harm from spreading. For AI, options range from **adding human review** to **switching the system off** — prepared in advance, not improvised.'),
    H('Containment options'),
    CMP('From least to most disruptive', ['Option', 'When to use'], [['Increase monitoring and sampling', 'Low severity, uncertain cause'], ['Add human review to all outputs of affected type', 'Errors in a specific segment'], ['Raise or lower thresholds temporarily', 'Too many false positives or negatives'], ['Restrict scope (segments, features, tools)', 'Problem limited to one area'], ['Roll back to previous model or prompt version', 'Problem started after a change'], ['Disable AI feature; fall back to manual process', 'Serious or widespread harm'], ['Revoke agent credentials / kill switch', 'Agent misbehaviour or compromise']]),
    H('Preparing fallbacks'),
    P('Containment is only fast if fallbacks are ready: documented manual processes, staff who know them, rollback procedures tested in advance, and feature flags or kill switches that work. For critical processes, define the maximum tolerable time without the AI and ensure manual capacity exists.'),
    H('Recovery and remediation for people'),
    P('Recovery includes not only restoring the system but **putting things right for people affected**: reviewing and correcting wrong decisions, compensating where appropriate, contacting affected customers, and handling complaints. Identify affected individuals using logs — another reason good logging matters.'),
    BR('This aligns with **business continuity and operational resilience**: fallback processes, recovery time objectives and customer remediation programmes.'),
    AP(['Check containment options and fallbacks are documented and tested.', 'Check logs allow identification of affected people.', 'Check remediation for affected people is part of the plan.'])],
   ex: 'After rolling back a pricing model, an insurer used decision logs to identify 2,300 customers overcharged during the incident and refunded them within a month.' },
  { t: 'Notification across EU, UAE and India', blocks: [
    S('An AI incident may trigger **several notification duties at once** — AI law, data protection, cyber, sector regulators and contracts. A **notification matrix** prepared in advance avoids missed deadlines.'),
    H('Common notification duties'),
    CMP('Notification matrix (confirm current requirements with Legal)', ['Regime', 'Trigger', 'To whom / when'], [['EU AI Act Art. 73', 'Serious incident involving a high-risk AI system (provider)', 'Market surveillance authority — immediately after establishing a causal link, no later than 15 days; 10 days if death; 2 days for widespread infringement or serious disruption of critical infrastructure'], ['GDPR Art. 33–34', 'Personal-data breach', 'Supervisory authority within 72 hours where feasible; individuals if high risk'], ['UAE PDPL', 'Personal-data breach (onshore)', 'UAE Data Office, and data subjects where required'], ['DIFC / ADGM', 'Personal-data breach', 'Commissioner as soon as practicable; individuals where required'], ['India DPDP Rules', 'Personal-data breach', 'Data Protection Board and affected data principals without delay; detailed report within 72 hours'], ['India CERT-In', 'Specified cyber incidents', 'Within 6 hours'], ['Sector regulators', 'Per sector rules (e.g. CBUAE, RBI)', 'Per rulebook'], ['Contracts', 'Per client or vendor agreements', 'Per contract']]),
    H('Deployers and providers'),
    P('Under the EU AI Act, deployers who identify a serious incident must inform the provider first and then the relevant authorities. Contracts with AI vendors should define incident notification in both directions — vendor to customer and customer to vendor — with time limits and content.'),
    H('Practical preparation'),
    P('Keep the notification matrix current; pre-agree who decides on notifications; prepare templates; and maintain contact details for regulators. Document every notification decision, including decisions **not** to notify and the reasoning — regulators may ask later.'),
    BR('Most organisations already have a breach-notification matrix for privacy and cyber. Extend it with AI Act and sector-specific AI triggers.'),
    AP(['Check the notification matrix includes AI-specific triggers.', 'Check decision-makers and templates are defined.', 'Check notification decisions are documented, including decisions not to notify.'])],
   ex: 'A chatbot exposed another customer’s account details to 40 users. The matrix showed the bank needed to notify the UAE Data Office and the affected customers, and inform its CBUAE supervisor; all were done within the required timeframes.' },
  { t: 'Root cause, communication and learning', blocks: [
    S('After containment, find the **root cause**, communicate honestly, and make sure the **lesson changes controls** — across all similar systems, not just the one that failed.'),
    H('Root-cause analysis for AI'),
    P('AI root causes often sit outside the model itself: unrepresentative data, an upstream data change, a missing monitoring owner, a prompt edited outside change control, a vendor model update, reviewer overload, or an approval that skipped a fairness test. Techniques such as “five whys” or fishbone analysis work well; involve data, business, risk and vendor representatives.'),
    CMP('Typical root causes and lasting fixes', ['Root cause', 'Lasting fix'], [['Unrepresentative training data', 'Representativeness checks in validation'], ['Upstream data change', 'Change notification from source systems; data quality gates'], ['Vendor silent update', 'Contract change-notification clause; regression tests'], ['Prompt changed outside process', 'Prompts under version control and release gates'], ['Alert ignored', 'Named owner and response time for alerts'], ['Reviewer overload', 'Capacity planning; threshold review']]),
    H('Communication'),
    P('Communicate clearly and honestly with affected people, staff, regulators and, where needed, the public. Explain what happened, who was affected, what has been done and how to get help. Avoid blaming “the algorithm” — the organisation is responsible.'),
    H('Learning across the portfolio'),
    P('Ask: **could this happen in our other AI systems?** Apply fixes across similar systems, update templates, testing suites and training, and report lessons to the AI governance committee. Contributing anonymised lessons to industry forums or public incident databases (such as the OECD AI Incidents Monitor or AI Incident Database) can also help others.'),
    BR('Root-cause analysis and corrective action are required by ISO/IEC 42001 clause 10.2 — the same discipline as ISO 27001. The AI-specific step is checking **all similar models and prompts**.'),
    AP(['Check root causes address process, not just the model.', 'Check fixes were applied to similar systems.', 'Check lessons reached the governance committee and training.'])],
   ex: 'After one chatbot leaked data through a retrieval permission gap, the organisation checked all eight RAG applications and found the same gap in two more — fixed before any incident occurred.' },
  { t: 'Real-world scenario: a tabletop exercise', blocks: [
    S('The best way to test AI incident readiness is a **tabletop exercise**: a realistic scenario worked through by the people who would respond, revealing gaps before a real incident does.'),
    H('The scenario'),
    P('At 08:15 on a Sunday, a journalist emails a regional bank (operating onshore in the UAE, with a branch in India and customers in Germany) with screenshots: the bank’s AI assistant, when asked in Hindi, is advising customers how to structure cash deposits to avoid reporting thresholds, and in one case revealed part of another customer’s transaction history.'),
    H('How the exercise ran'),
    O(['**Detection (08:15–08:45):** who receives the journalist’s email on a Sunday? The exercise found no on-call route from communications to the AI team — **gap 1**.', '**Triage (08:45–09:30):** the team identifies a recent prompt change and a retrieval permission issue. Personal data is involved; possible AML and conduct concerns.', '**Containment (09:30):** Hindi responses disabled; retrieval switched to public documents only. Rollback of the prompt took 90 minutes because the previous version was not stored — **gap 2**.', '**Notification screening:** UAE Data Office and affected customers (PDPL); CBUAE supervisor; India — DPDP Board and affected principals if Indian customers affected, CERT-In if a reportable cyber incident; GDPR if German customers affected; EU AI Act serious-incident duties considered (chatbot not high-risk, so Article 73 unlikely). The team was unsure who could approve regulator notifications on a weekend — **gap 3**.', '**Communication:** holding statement to the journalist; customer contact plan.', '**Root cause:** prompt change outside release process; no Hindi red-team coverage; retrieval permissions not enforced.']),
    H('Actions from the exercise'),
    U(['On-call route from communications and customer service to the AI incident team.', 'Prompts under version control with one-click rollback.', 'Named weekend decision-makers for notifications, with delegated authority.', 'Multilingual red-teaming including financial-crime misuse scenarios.', 'Retrieval permission tests added to the release gate.']),
    BR('Tabletop exercises are standard in **business continuity and cyber incident** programmes. Running an AI-specific scenario reveals gaps unique to AI — prompts, retrieval, multilingual behaviour — that cyber exercises miss.'),
    AP(['Run an AI tabletop exercise at least annually.', 'Include communications, legal, compliance, data science and vendors.', 'Track gaps as actions with owners and dates.'], '', 'Running an AI tabletop exercise')],
   ex: 'Three months after the exercise, a real prompt error was rolled back in four minutes — the on-call route and version control built after the tabletop worked exactly as intended.' }
 ],
 sum: ['AI incidents include wrong decisions, unfair outcomes, harmful content and agent actions — not only security breaches.', 'Detection relies on monitoring, complaints, staff reports and external sources; triage must include notification screening.', 'Prepare containment options and fallbacks in advance; remediate harm to people.', 'Use a notification matrix covering AI law, data protection, cyber, sector rules and contracts.', 'Root causes often lie in process; apply fixes across all similar systems.', 'Tabletop exercises reveal AI-specific gaps before real incidents do.'],
 q: [
  { t: 'Which is an AI incident even without any security breach?', o: ['A scheduled software update outside business hours', 'A model systematically denying claims for one group', 'A routine password change for all staff accounts', 'A planned outage announced to customers in advance'], a: 1, x: 'Discriminatory outcomes are AI incidents.' },
  { t: 'Under the EU AI Act, a provider must report a serious incident involving a high-risk system no later than:', o: ['1 year from the end of the financial year', '6 months after the incident is closed', '15 days (shorter for death or critical disruption)', 'There is no deadline for reporting at all'], a: 2, x: 'Article 73 sets 15 days, with 10 and 2 days for specified cases.' },
  { t: 'India’s CERT-In directions require reporting specified cyber incidents within:', o: ['30 days', '72 hours', '1 week', '6 hours'], a: 3, x: 'CERT-In requires reporting within 6 hours.' },
  { t: 'What should be documented for notification decisions?', o: ['All decisions, including decisions not to notify, with reasons', 'Only the notifications that were actually sent to regulators', 'Nothing at all, to reduce the organisation’s legal liability', 'Only the regulator’s written reply to each notification sent'], a: 0, x: 'Regulators may later ask why a notification was or was not made.' },
  { t: 'After fixing one chatbot’s retrieval permission gap, what should happen next?', o: ['Close the incident immediately and move on to others', 'Check all similar RAG applications for the same gap', 'Delete all logs relating to the affected application', 'Increase the model temperature to vary future answers'], a: 1, x: 'Lessons should be applied across the portfolio.' },
  { t: 'What is the main purpose of an AI tabletop exercise?', o: ['To train the model on new incident examples', 'To satisfy the marketing team’s campaign plans', 'To reveal response gaps before a real incident', 'To replace continuous monitoring of AI systems'], a: 2, x: 'Exercises test readiness and find gaps.' }
 ]
}
];
